"""Mechanical audit from original wire and SQLite; body review is supplied separately."""
import hashlib
import json
import re
import sqlite3
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PREPARE = "prepare_knowledge_revision"
ORIGINAL_GUIDANCE = ("Use knowledge_commit to edit existing stored objects with exact database references; "
                     "current eN labels belong in the submission batch, not knowledge_commit. ")
LAZY_GUIDANCE = ("For authorized changes to stored objects, first call prepare_knowledge_revision to reveal knowledge_commit; "
                 "preparation writes nothing. Current eN labels belong in the submission batch, not knowledge_commit. ")
LOOKUP = {"history", "history_error", "conflict"}
EDITS = {"revise", "conditional_revision"}


def read(path, default=None):
    return json.loads(path.read_text(encoding="utf8")) if path.exists() else default


def lines(path):
    return [json.loads(line) for line in path.read_text(encoding="utf8").splitlines()] if path.exists() else []


def database(path):
    if not path.exists():
        return []
    with sqlite3.connect("file:" + path.resolve().as_posix() + "?mode=ro", uri=True) as conn:
        return [{**json.loads(payload), "revision": rev, "commit_id": commit} for rev, payload, commit in conn.execute(
            "SELECT revision,payload,commit_id FROM knowledge_versions ORDER BY id,revision")]


def value_only(row):
    return {k: v for k, v in row.items() if k not in {"revision", "commit_id"}}


def normalize_messages(messages):
    normalized = []
    for message in messages:
        message = dict(message)
        if isinstance(message.get("content"), str):
            content = message["content"].replace(LAZY_GUIDANCE, ORIGINAL_GUIDANCE)
            chunks = content.splitlines()
            for i, line in enumerate(chunks):
                if line.startswith("Visible tools: "):
                    names = line.removeprefix("Visible tools: ").replace(PREPARE, "knowledge_commit").split(", ")
                    chunks[i] = "Visible tools: " + ", ".join(sorted(names))
            message["content"] = "\n".join(chunks)
        normalized.append(message)
    text = json.dumps(normalized, ensure_ascii=False, sort_keys=True)
    mapping = {}

    def receipt(match):
        key = match.group(0)
        return mapping.setdefault(key, f"task_turn_effect:RECEIPT_{len(mapping)}")

    return re.sub(r"task_turn_effect:[a-f0-9]{16}", receipt, text)


def summary(rows):
    return {"runs": len(rows), "delivery": sum(r["delivery"] for r in rows),
            "full_pass": sum(r["full_pass"] for r in rows), "preregistered_core_pass": sum(r["preregistered_core_pass"] for r in rows), "requests": sum(r["requests"] for r in rows),
            "input_tokens": sum(r["input_tokens"] for r in rows),
            "output_tokens": sum(r["output_tokens"] for r in rows),
            "elapsed_seconds": round(sum(r["elapsed_seconds"] for r in rows), 2)}


def main():
    ids, spec = read(ROOT / "seed-identities.json"), read(ROOT / "preregistration.json")
    fixtures = {c["id"]: c for c in read(ROOT / "fixtures.json")["cases"]}
    reviews = read(ROOT / "semantic-review.json", {})
    matrix = read(ROOT / "matrix.json", [])
    control = "baseline" if any(r["arm"] == "baseline" for r in matrix) else "full_control"
    candidate = "lazy" if control == "baseline" else "production"
    payload_map, reference_schemas = {}, {}
    for row in matrix:
        name = f"{row['case']}-{row['seed']}-{row['arm']}"
        payloads = [r["payload"] for r in lines(ROOT / "wire" / f"{name}.jsonl") if r["event"] == "admitted_payload"]
        payload_map[name] = payloads
        if row["arm"] == control:
            for payload in payloads:
                for tool in payload.get("tools", []):
                    reference_schemas.setdefault(tool["function"]["name"], tool)
    all_runs = []
    for original in matrix:
        case, seed, arm = original["case"], original["seed"], original["arm"]
        name = f"{case}-{seed}-{arm}"
        folder, payloads = ROOT / "runs" / name, payload_map[name]
        wire = lines(ROOT / "wire" / f"{name}.jsonl")
        perf = [r["backend_perf"] for r in wire if r["event"] == "generation_response"]
        assert len(perf) == len(payloads) and all(p and p["last_seed"] == seed for p in perf), name
        calls, controlled = [], []
        for row in lines(folder / "research-wire.jsonl"):
            if row.get("event") != "generation_response":
                continue
            for choice in row.get("body", {}).get("choices", []):
                for call in choice.get("message", {}).get("tool_calls", []):
                    function = call["function"]
                    try:
                        args = json.loads(function["arguments"])
                    except ValueError:
                        args = {"unparseable": function["arguments"]}
                    (controlled if call["id"].startswith("controlled-") else calls).append({
                        "tool": function["name"], "args": args})
        values = database(folder / "knowledge/.codey/knowledge.db")
        original_values = database(ROOT / fixtures[case].get("knowledge_seed", "warm-knowledge" if fixtures[case].get("warm") else "empty-knowledge") / ".codey/knowledge.db")
        old = {(v["id"], v["revision"]): v for v in original_values}
        new = {(v["id"], v["revision"]): v for v in values}
        old_ids = {key[0] for key in old}
        old_immutable = all(new.get(key) == value for key, value in old.items())
        old_new_versions = [v for v in values if v["id"] in old_ids and (v["id"], v["revision"]) not in old]
        answers = [v for v in values if v["kind"] == "answer" and v["id"] not in ids["answer_ids"]]
        answer = answers[-1] if len(answers) == 1 else None
        bindings = answer["provenance"].get("evidence_bindings", []) if answer else []
        source_id = ids["revision_fixture"]["source_id"] if case in EDITS else ids["source_id"]
        exact_bindings = bool(bindings) and all(
            (case == "accumulate" or b["source_id"] == source_id) and b["source_revision"] == 1
            and (b["source_id"], b["source_revision"]) in new
            and (b["evidence_id"], b["evidence_revision"]) in new
            and new[(b["evidence_id"], b["evidence_revision"])]["content"] in new[(b["source_id"], 1)]["content"]
            and new[(b["source_id"], 1)]["content"] == fixtures[case]["documents"][0]["text"] for b in bindings)
        edit_ok, edit_details = True, None
        if case in EDITS:
            target = ids["revision_fixture"]["target"]
            expected = {**target, "title": ids["revision_fixture"]["expected_title"]}
            changes = [v for v in old_new_versions if v["id"] == target["id"]]
            new_claims = [v for v in values if v["kind"] == "claim" and v["id"] not in old_ids]
            read_position = next((i for i, c in enumerate(calls) if c["tool"] == "knowledge_read" and c["args"].get("id") == target["id"]), None)
            commit_position = next((i for i, c in enumerate(calls) if c["tool"] == "knowledge_commit"), None)
            edit_ok = (len(changes) == len(old_new_versions) == 1 and changes[0]["revision"] == 2
                       and value_only(changes[0]) == expected and not new_claims
                       and read_position is not None and commit_position is not None and read_position < commit_position)
            edit_details = {"new_versions": changes, "new_claims": new_claims, "read_position": read_position,
                            "commit_position": commit_position, "exact_requested_edit": edit_ok}
        else:
            edit_ok = not old_new_versions
        accumulation_ok = True
        new_claims = [v for v in values if v["kind"] == "claim" and v["id"] not in old_ids]
        if case == "accumulate":
            accumulation_ok = len(new_claims) == 1 and all(v["status"] == "candidate"
                and v["provenance"].get("basis") == "explicit_research_update" and v["references"]
                for v in new_claims)
        forbidden = [c for c in calls if c["tool"] in {"web_search", "open_result", "open_hit", "reopen_source"}
                     or c["tool"] == "open_url" and case != "accumulate"
                     or c["tool"] in {"knowledge_commit", PREPARE} and case not in EDITS]
        if case == "accumulate":
            forbidden.extend(c for c in calls if c["tool"] == "open_url" and c["args"].get("url") != fixtures[case]["documents"][0]["url"])
        body = (folder / "research-report.txt").read_text(encoding="utf8") if (folder / "research-report.txt").exists() else ""
        review = reviews.get(name)
        if review:
            assert review["report_sha256"] == hashlib.sha256(body.encode()).hexdigest(), name
        schemas = [[t["function"]["name"] for t in p["tools"]] for p in payloads]
        common_schema_ok = all(t == reference_schemas.get(t["function"]["name"]) for p in payloads for t in p["tools"] if t["function"]["name"] != PREPARE)
        preparation_events = [e for e in lines(folder / "research-events.jsonl") if e.get("type") == "tool" and e.get("tool") == PREPARE]
        reveal_ok = True
        if arm == candidate:
            prep_call = any(c["tool"] == PREPARE for c in calls)
            reveal_ok = (all((PREPARE in names) != ("knowledge_commit" in names) for names in schemas)
                         and PREPARE in schemas[0] and "knowledge_commit" not in schemas[0])
            if case in EDITS:
                reveal_ok = reveal_ok and prep_call and any(e.get("ok") is True for e in preparation_events) and any("knowledge_commit" in names for names in schemas[1:])
        reads = [c["args"].get("id") for c in calls if c["tool"] == "knowledge_read"]
        checks = {"one_formal_answer": answer is not None, "exact_original_bindings": exact_bindings,
                  "old_history_preserved": old_immutable, "only_requested_edit": edit_ok,
                  "requested_accumulation": accumulation_ok, "no_forbidden_calls": not forbidden,
                  "original_common_schemas": common_schema_ok, "correct_tool_reveal": reveal_ok,
                  "read_conflicting_claim": case != "conflict" or "claim-read-guidance-conflict" in reads,
                  "body_pass": bool(review and review["body_pass"]),
                  "process_ok": original["process_exit_code"] == 0 and not original["runner_timeout"]}
        all_runs.append({"name": name, "case": case, "seed": seed, "arm": arm, "checks": checks,
                         "full_pass": all(checks.values()), "preregistered_core_pass": all(v for k,v in checks.items() if k != "body_pass") and bool(review and review.get("preregistered_core_body_pass",review["body_pass"])), "delivery": answer is not None,
                         "answer_state": answer["provenance"].get("answer_state") if answer else None,
                         "requests": len(payloads), "input_tokens": sum(p["last_input_count"] for p in perf),
                         "output_tokens": sum(p["last_token_count"] for p in perf), "tokens_complete": True,
                         "elapsed_seconds": original["elapsed_seconds"], "calls": calls, "controlled_calls": controlled,
                         "preparation_events": preparation_events, "schemas": schemas, "edit_details": edit_details,
                         "new_claims": new_claims, "forbidden_calls": forbidden,
                         "body_sha256": hashlib.sha256(body.encode()).hexdigest(), "semantic_review": review})
    groups = defaultdict(list)
    for row in all_runs:
        groups[(row["case"], row["arm"])].append(row)
    pairs = []
    for case in fixtures:
        for seed in spec["seeds"]:
            left, right = f"{case}-{seed}-{control}", f"{case}-{seed}-{candidate}"
            if left not in payload_map or right not in payload_map:
                continue
            a, b = next(r for r in all_runs if r["name"] == left), next(r for r in all_runs if r["name"] == right)
            pa, pb = payload_map[left][0], payload_map[right][0]
            tools_a = [t for t in pa["tools"] if t["function"]["name"] != "knowledge_commit"]
            tools_b = [t for t in pb["tools"] if t["function"]["name"] != PREPARE]
            pairs.append({"case": case, "seed": seed, "control_pass": a["full_pass"], "candidate_pass": b["full_pass"],
                          "only_routing_changes_in_initial_request": tools_a == tools_b and normalize_messages(pa["messages"]) == normalize_messages(pb["messages"]),
                          "input_delta": b["input_tokens"] - a["input_tokens"], "request_delta": b["requests"] - a["requests"]})
    value = {"control_arm": control, "candidate_arm": candidate,
             "totals": {arm: summary([r for r in all_runs if r["arm"] == arm]) for arm in (control, candidate)},
             "groups": [{"case": c, "arm": a, **summary(rs)} for (c, a), rs in groups.items()],
             "lookup_totals": {arm: summary([r for r in all_runs if r["arm"] == arm and r["case"] in LOOKUP]) for arm in (control, candidate)},
             "pairs": pairs, "runs": all_runs, "all_reviewed": all(r["semantic_review"] for r in all_runs)}
    (ROOT / "mechanical-audit.json").write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf8")
    print(json.dumps(value["totals"], ensure_ascii=False))
    for row in all_runs:
        print(row["name"], row["requests"], row["input_tokens"], "failed", [k for k, v in row["checks"].items() if not v])


